begin;
select plan(118);

-- Structural boundary and canonical field contract (AR-001--AR-004, AR-022, AR-062--AR-064, AR-087, AR-090--AR-091)
select has_table('bios_knowledge','sources','AR-001/002 sources exists');
select has_table('bios_knowledge','source_documents','AR-002 source_documents exists');
select results_eq($$select count(*)::bigint from pg_catalog.pg_tables where schemaname='bios_knowledge' and tablename in ('sources','source_documents')$$,array[2::bigint],'AR-002 exactly two owned tables');
select is_empty($$select 1 from information_schema.tables where table_schema like 'bios_%' and table_name in ('source_types','source_versions','source_retrievals','source_locations','connectors','ingestion_jobs','document_contents','evidence','provenance','intelligence','vectors','chunks','clients','workspaces')$$,'AR-003 deferred tables remain absent');
select results_eq($$select (select count(*) from bios_knowledge.sources)+(select count(*) from bios_knowledge.source_documents)$$,array[0::bigint],'AR-004 zero production seeds');
select is_empty($$select 1 from information_schema.columns where table_schema='bios_knowledge' and table_name='sources' and column_name in ('source_type_id','reliability_score','entity_id','market_id','domain_id','connector_id','credential_id','content')$$,'AR-022 excluded Source fields absent');
select is_empty($$select 1 from information_schema.tables where table_schema like 'bios_%' and table_name like '%locator%' and table_name<>'source_documents'$$,'AR-062 no locator table');
select is_empty($$select 1 from information_schema.columns where table_schema='bios_knowledge' and table_name in ('sources','source_documents') and column_name in ('market_id','geography_id','domain_id','domain_node_id','entity_id')$$,'AR-063 no taxonomy/geography/entity coupling');
select is_empty($$select 1 from information_schema.columns where table_schema='bios_knowledge' and table_name='source_documents' and column_name in ('raw_content','derived_content','storage_key','retrieved_at','ingestion_status','chunk_id','vector','evidence_id','claim_id')$$,'AR-064 no content or evidence fields');
select is_empty($$select 1 from pg_catalog.pg_constraint where connamespace='bios_governance'::regnamespace and conname='audit_action_check' and pg_get_constraintdef(oid) ~ 'source\\.'$$,'AR-087 no Source-specific audit action');
select results_eq($$select count(*)::bigint from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace where n.nspname='bios_knowledge' and c.relname in ('sources','source_documents') and c.relrowsecurity$$,array[2::bigint],'AR-090/091 deterministic RLS catalog');

-- Foundation fixtures.
insert into bios_core.tenants(id,code,name,status,activated_at) values
 ('a5000000-0000-0000-0000-000000000001','source_tenant_a','Source Tenant A','active',statement_timestamp()),
 ('a5000000-0000-0000-0000-000000000002','source_tenant_b','Source Tenant B','active',statement_timestamp());
insert into bios_core.languages(id,tag,base_language_subtag,display_name,status,activated_at) values
 ('a5100000-0000-0000-0000-000000000001','en','en','English','active',statement_timestamp());
select set_config('request.jwt.claims','{"role":"service_role"}',true);

select throws_ok($$insert into bios_knowledge.sources(code,canonical_name,knowledge_scope) values('A','Bad','shared')$$,'23514',null,'AR-006 Source code bound/regex');
select throws_ok($$insert into bios_knowledge.sources(code,canonical_name,knowledge_scope) values('valid_code',' Bad ','shared')$$,'23514',null,'AR-009 Source name trim/bound');
select throws_ok($$insert into bios_knowledge.sources(code,canonical_name,description,knowledge_scope) values('valid_desc','Valid','', 'shared')$$,'23514',null,'AR-010 Source description rule');
select throws_ok($$insert into bios_knowledge.sources(code,canonical_name,canonical_origin_uri,knowledge_scope) values('valid_uri','Valid',repeat('x',2049),'shared')$$,'23514',null,'AR-010 Source URI bound');
select throws_ok($$insert into bios_knowledge.sources(code,canonical_name,knowledge_scope) values('scope_bad','Bad','global')$$,'23514',null,'AR-012 exact Source scope');
select throws_ok($$insert into bios_knowledge.sources(code,canonical_name,knowledge_scope,tenant_id) values('scope_bad2','Bad','shared','a5000000-0000-0000-0000-000000000001')$$,'23514',null,'AR-013 shared Source null Tenant');
select throws_ok($$insert into bios_knowledge.sources(code,canonical_name,knowledge_scope) values('scope_bad3','Bad','tenant')$$,'23514',null,'AR-013 tenant Source requires Tenant');

select lives_ok($$select bios_internal.create_source('shared_src','Shared Source',null,'https://example.test','shared',null,'migration-005-test')$$,'AR-005 generated Source UUID');
select lives_ok($$select bios_internal.create_source('shared_src2','Shared Source',null,'https://example.test','shared',null,'migration-005-test')$$,'AR-009/011 duplicate name and URI allowed');
select throws_ok($$select bios_internal.create_source('shared_src','Duplicate',null,null,'shared',null,'migration-005-test')$$,'23505',null,'AR-007 shared code unique');
select lives_ok($$select bios_internal.create_source('shared_src','Tenant A Source',null,null,'tenant','a5000000-0000-0000-0000-000000000001','migration-005-test')$$,'AR-008 same code across scope');
select lives_ok($$select bios_internal.create_source('shared_src','Tenant B Source',null,null,'tenant','a5000000-0000-0000-0000-000000000002','migration-005-test')$$,'AR-008 same code across Tenants');
select throws_ok($$select bios_internal.create_source('shared_src','Tenant A Duplicate',null,null,'tenant','a5000000-0000-0000-0000-000000000001','migration-005-test')$$,'23505',null,'AR-007 tenant-local code unique');
select results_eq($$select distinct status from bios_knowledge.sources$$,array['candidate'],'AR-015 Source starts candidate');
select throws_ok($$update bios_knowledge.sources set id=gen_random_uuid() where code='shared_src2' and knowledge_scope='shared'$$,'P0001','Source identity and ownership are immutable','AR-005 Source UUID immutable');
select throws_ok($$update bios_knowledge.sources set tenant_id='a5000000-0000-0000-0000-000000000002' where code='shared_src' and knowledge_scope='tenant' and tenant_id='a5000000-0000-0000-0000-000000000001'$$,'P0001','Source identity and ownership are immutable','AR-014 ownership immutable');
select lives_ok($$select bios_internal.transition_source((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'active','approve','migration-005-test')$$,'AR-016 candidate-active');
select throws_ok($$select bios_internal.transition_source((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'candidate','reverse','migration-005-test')$$,'P0001','invalid Source transition','AR-016 invalid transition rejected');
select lives_ok($$select bios_internal.transition_source((select id from bios_knowledge.sources where code='shared_src2'),'deprecated','reject','migration-005-test')$$,'AR-016 candidate-deprecated');
select throws_ok($$select bios_internal.transition_source((select id from bios_knowledge.sources where code='shared_src2'),'active','reverse','migration-005-test')$$,'P0001','invalid Source transition','AR-017 deprecated terminal');

-- Document bounds, identity, compatibility and creation (AR-023--AR-048, AR-093--AR-096).
select throws_ok($$insert into bios_knowledge.source_documents(source_id,knowledge_scope,canonical_title,access_classification) values(gen_random_uuid(),'shared','Missing','public')$$,'P0002',null,'AR-023 valid Source required');
select throws_ok($$insert into bios_knowledge.source_documents(source_id,knowledge_scope,canonical_title,access_classification) values((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'global','Bad','public')$$,'23514',null,'AR-025 exact Document scope');
select throws_ok($$insert into bios_knowledge.source_documents(source_id,knowledge_scope,tenant_id,canonical_title,access_classification) values((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared','a5000000-0000-0000-0000-000000000001','Bad','public')$$,'P0001','shared Document requires shared Source','AR-026 shared Document null Tenant');
select lives_ok($$select bios_internal.create_source_document((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared',null,'doc-1','Document One',null,'url','https://example.test/doc',null,'single','a5100000-0000-0000-0000-000000000001','application/pdf','public',null,null,'migration-005-test')$$,'AR-024/048/094 active-Source candidate creation');
select lives_ok($$select bios_internal.create_source_document((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'tenant','a5000000-0000-0000-0000-000000000001','doc-1','Tenant Copy',null,null,null,null,'unknown',null,null,'public',null,null,'migration-005-test')$$,'AR-027/030 tenant copy of shared Source');
select lives_ok($$select bios_internal.create_source_document((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='tenant' and tenant_id='a5000000-0000-0000-0000-000000000001'),'tenant','a5000000-0000-0000-0000-000000000001',null,'Candidate Source Document',null,null,null,null,'multiple',null,null,'restricted',null,null,'migration-005-test')$$,'AR-027/093 candidate-Source creation');
select throws_ok($$select bios_internal.create_source_document((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='tenant' and tenant_id='a5000000-0000-0000-0000-000000000001'),'tenant','a5000000-0000-0000-0000-000000000002',null,'Cross tenant',null,null,null,null,'unknown',null,null,'public',null,null,'migration-005-test')$$,'P0001','cross-Tenant Source is prohibited','AR-028 cross-Tenant rejected');
select throws_ok($$select bios_internal.create_source_document((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='tenant' and tenant_id='a5000000-0000-0000-0000-000000000001'),'shared',null,null,'Shared from private',null,null,null,null,'unknown',null,null,'public',null,null,'migration-005-test')$$,'P0001','shared Document requires shared Source','AR-028 tenant Source cannot produce shared');
select throws_ok($$select bios_internal.create_source_document((select id from bios_knowledge.sources where code='shared_src2'),'shared',null,null,'Deprecated source',null,null,null,null,'unknown',null,null,'public',null,null,'migration-005-test')$$,'P0001','new Document requires candidate or active Source','AR-020/095 deprecated Source rejects creation');
select throws_ok($$select bios_internal.transition_source_document((select id from bios_knowledge.source_documents where canonical_title='Candidate Source Document'),'active','premature','migration-005-test')$$,'P0001','Document activation requires active Source','AR-096 candidate Source blocks activation');
select throws_ok($$insert into bios_knowledge.source_documents(source_id,knowledge_scope,document_identifier,canonical_title,access_classification) values((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared',' ','Bad','public')$$,'23514',null,'AR-030 identifier bound');
select throws_ok($$select bios_internal.create_source_document((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared',null,'doc-1','Duplicate identifier',null,null,null,null,'unknown',null,null,'public',null,null,'migration-005-test')$$,'23505',null,'AR-030 identifier scope uniqueness');
select throws_ok($$insert into bios_knowledge.source_documents(source_id,knowledge_scope,canonical_title,access_classification) values((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared',' Bad ','public')$$,'23514',null,'AR-031 title trim/bound');
select throws_ok($$insert into bios_knowledge.source_documents(source_id,knowledge_scope,canonical_title,description,access_classification) values((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared','Good','', 'public')$$,'23514',null,'AR-032 description rule');
select throws_ok($$insert into bios_knowledge.source_documents(source_id,knowledge_scope,canonical_title,locator_scheme,access_classification) values((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared','Bad locator','url','public')$$,'23514',null,'AR-033 locator pair');
select throws_ok($$insert into bios_knowledge.source_documents(source_id,knowledge_scope,canonical_title,locator_scheme,canonical_locator,access_classification) values((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared','Bad scheme','ftp','x','public')$$,'23514',null,'AR-034 locator vocabulary');
select lives_ok($$select bios_internal.create_source_document((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared',null,null,'Duplicate Locator',null,'url','https://example.test/doc',null,'unknown',null,null,'restricted',null,null,'migration-005-test')$$,'AR-035 duplicate locator accepted');
select lives_ok($$select bios_internal.update_source_document_metadata((select id from bios_knowledge.source_documents where canonical_title='Duplicate Locator'),'Corrected Locator Title',null,statement_timestamp(),'unknown',null,null,'restricted',null,'factual correction','migration-005-test')$$,'AR-031/036 title and publication correctable');
select throws_ok($$insert into bios_knowledge.source_documents(source_id,knowledge_scope,canonical_title,language_mode,access_classification) values((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared','Bad language','invalid','public')$$,'23514',null,'AR-037 language vocabulary');
select throws_ok($$insert into bios_knowledge.source_documents(source_id,knowledge_scope,canonical_title,language_mode,access_classification) values((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared','Missing language','single','public')$$,'P0001','active Language required','AR-038 single requires Language');
select throws_ok($$select bios_internal.create_source_document((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared',null,null,'Inactive language',null,null,null,null,'single',gen_random_uuid(),null,'public',null,null,'migration-005-test')$$,'P0001','active Language required','AR-038 active Language required');
select ok((select language_id is not null and status='candidate' from bios_knowledge.source_documents where canonical_title='Document One'),'AR-039 Language relationship is non-cascading history');
select throws_ok($$insert into bios_knowledge.source_documents(source_id,knowledge_scope,canonical_title,media_type,access_classification) values((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared','Bad media','Application/PDF','public')$$,'23514',null,'AR-040 media type regex');
select throws_ok($$update bios_knowledge.source_documents set content_sha256='ABC' where canonical_title='Document One'$$,'23514',null,'AR-041 digest format');
select lives_ok($$select bios_internal.register_source_document_digest((select id from bios_knowledge.source_documents where canonical_title='Document One'),repeat('a',64),'digest','migration-005-test')$$,'AR-041 digest registered once');
select throws_ok($$select bios_internal.register_source_document_digest((select id from bios_knowledge.source_documents where canonical_title='Document One'),repeat('b',64),'replace','migration-005-test')$$,'P0001','Document digest already registered','AR-041 digest immutable');
select lives_ok($$select bios_internal.register_source_document_digest((select id from bios_knowledge.source_documents where canonical_title='Corrected Locator Title'),repeat('a',64),'same bytes','migration-005-test')$$,'AR-042 duplicate digest allowed');
select throws_ok($$insert into bios_knowledge.source_documents(source_id,knowledge_scope,canonical_title,access_classification) values((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared','Bad access','secret')$$,'23514',null,'AR-043 access vocabulary');
select throws_ok($$insert into bios_knowledge.source_documents(source_id,knowledge_scope,canonical_title,access_classification) values((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared','Bad shared access','tenant_confidential')$$,'23514',null,'AR-044 shared tenant-confidential rejected');
select ok((select knowledge_scope='tenant' from bios_knowledge.source_documents where canonical_title='Tenant Copy' and access_classification='public'),'AR-045 public classification remains tenant-private');
select throws_ok($$insert into bios_knowledge.source_documents(source_id,knowledge_scope,canonical_title,access_classification,restriction_note) values((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared','Bad note','public','')$$,'23514',null,'AR-046 restriction note rule');
select ok((select restriction_note is null from bios_knowledge.source_documents where canonical_title='Document One'),'AR-047 restriction note optional and non-authorizing');

-- Lifecycle, correction, supersession and Source dependency.
select lives_ok($$select bios_internal.transition_source_document((select id from bios_knowledge.source_documents where canonical_title='Document One'),'active','approve','migration-005-test')$$,'AR-049 active Source/language activation');
select throws_ok($$select bios_internal.transition_source_document((select id from bios_knowledge.source_documents where canonical_title='Document One'),'candidate','reverse','migration-005-test')$$,'P0001','invalid Document transition','AR-050 lifecycle direction');
select lives_ok($$select bios_internal.transition_source_document((select id from bios_knowledge.source_documents where canonical_title='Corrected Locator Title'),'archived','archive','migration-005-test')$$,'AR-050 candidate-archived');
select throws_ok($$select bios_internal.transition_source_document((select id from bios_knowledge.source_documents where canonical_title='Corrected Locator Title'),'active','reverse','migration-005-test')$$,'P0001','invalid Document transition','AR-051 archived terminal');
select throws_ok($$update bios_knowledge.source_documents set source_id=(select id from bios_knowledge.sources where code='shared_src2') where canonical_title='Document One'$$,'P0001','Document identity is immutable','AR-029 identity fields immutable');
select throws_ok($$insert into bios_knowledge.source_documents(id,source_id,knowledge_scope,canonical_title,access_classification,supersedes_document_id) values('a5200000-0000-0000-0000-000000000001',(select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'shared','Self successor','public','a5200000-0000-0000-0000-000000000001')$$,'P0001','Document cannot supersede itself','AR-052 self-supersession rejected');
select lives_ok($$select bios_internal.create_source_document((select source_id from bios_knowledge.source_documents where canonical_title='Document One'),'shared',null,'doc-2','Document Two',null,null,null,null,'unknown',null,null,'public',null,(select id from bios_knowledge.source_documents where canonical_title='Document One'),'migration-005-test')$$,'AR-053 compatible active predecessor');
select throws_ok($$select bios_internal.create_source_document((select source_id from bios_knowledge.source_documents where canonical_title='Document One'),'shared',null,'doc-3','Document Three',null,null,null,null,'unknown',null,null,'public',null,(select id from bios_knowledge.source_documents where canonical_title='Document One'),'migration-005-test')$$,'23505',null,'AR-054 one candidate successor');
select lives_ok($$select bios_internal.transition_source_document((select id from bios_knowledge.source_documents where canonical_title='Document Two'),'active','new revision','migration-005-test')$$,'AR-055 atomic supersession');
select results_eq($$select status from bios_knowledge.source_documents where canonical_title='Document One'$$,array['superseded'],'AR-055 predecessor superseded');
select lives_ok($$select bios_internal.create_source_document((select source_id from bios_knowledge.source_documents where canonical_title='Document Two'),'shared',null,'doc-3','Document Three',null,null,null,null,'unknown',null,null,'public',null,(select id from bios_knowledge.source_documents where canonical_title='Document Two'),'migration-005-test')$$,'AR-058 successor has distinct UUID');
select lives_ok($$select bios_internal.transition_source_document((select id from bios_knowledge.source_documents where canonical_title='Document Three'),'archived','withdraw','migration-005-test')$$,'AR-056 archive releases proposal');
select lives_ok($$select bios_internal.create_source_document((select source_id from bios_knowledge.source_documents where canonical_title='Document Two'),'shared',null,'doc-4','Document Four',null,null,null,null,'unknown',null,null,'public',null,(select id from bios_knowledge.source_documents where canonical_title='Document Two'),'migration-005-test')$$,'AR-056 replacement proposal succeeds');
select throws_ok($$select bios_internal.create_source_document((select source_id from bios_knowledge.source_documents where canonical_title='Document One'),'shared',null,null,'Late Successor',null,null,null,null,'unknown',null,null,'public',null,(select id from bios_knowledge.source_documents where canonical_title='Document One'),'migration-005-test')$$,'P0001','incompatible successor proposal','AR-057 superseded predecessor closed');
select ok((select p.source_id=s.source_id from bios_knowledge.source_documents p join bios_knowledge.source_documents s on s.supersedes_document_id=p.id where p.canonical_title='Document One'),'AR-059 no content/reference movement');
select ok((select count(*)>=2 from bios_knowledge.source_documents where canonical_locator is null),'AR-060 metadata does not auto-deduplicate');
select ok((select count(*)=2 from bios_knowledge.source_documents where document_identifier='doc-1'),'AR-061 cross-scope copies distinct');
select throws_ok($$select bios_internal.transition_source((select source_id from bios_knowledge.source_documents where canonical_title='Document Two'),'deprecated','still used','migration-005-test')$$,'P0001','Source has candidate or active Documents','AR-018 active/candidate Documents block deprecation');
select ok((select source_id is not null and status='superseded' from bios_knowledge.source_documents where canonical_title='Document One'),'AR-019 historical Document remains attached');

select lives_ok($$select bios_internal.update_source_document_metadata((select id from bios_knowledge.source_documents where canonical_title='Document Four'),'Document Four Corrected','candidate correction',null,'multiple',null,'text/html','restricted','note','correction','migration-005-test')$$,'AR-065 candidate correction matrix');
select lives_ok($$select bios_internal.update_source_document_metadata((select id from bios_knowledge.source_documents where canonical_title='Document Two'),'Document Two Corrected','active correction',null,'unknown',null,'application/pdf','public',null,'correction','migration-005-test')$$,'AR-066 active correction matrix');
select lives_ok($$select bios_internal.update_source_document_metadata((select id from bios_knowledge.source_documents where canonical_title='Document One'),'Document One Historical','history correction',null,'single','a5100000-0000-0000-0000-000000000001','application/pdf','public',null,'correction','migration-005-test')$$,'AR-067 historical correction');
select throws_ok($$select bios_internal.update_source_document_metadata((select id from bios_knowledge.source_documents where canonical_title='Document Two Corrected'),'No access change',null,null,'unknown',null,null,'restricted',null,'bad','migration-005-test')$$,'P0001','access classification is immutable after activation','AR-068 post-activation access immutable');

-- Security, audit, concurrency, regressions, and Source metadata matrix.
select results_eq($$select count(*)::bigint from pg_policies where schemaname='bios_knowledge' and tablename in ('sources','source_documents')$$,array[2::bigint],'AR-069--075 RLS policies installed');
select ok(not has_table_privilege('anon','bios_knowledge.sources','select'),'AR-069 anonymous Source read denied');
select ok(not has_table_privilege('anon','bios_knowledge.source_documents','select'),'AR-069 anonymous Document read denied');
select ok((select qual ~ 'status = ''active''' from pg_policies where tablename='sources'),'AR-070 active shared Source read predicate');
select ok((select qual ~ 'access_classification = ''public''' from pg_policies where tablename='source_documents'),'AR-071 public shared Document predicate');
select ok((select qual !~ 'licensed.*OR.*restricted' from pg_policies where tablename='source_documents'),'AR-072 licensed/restricted not generally exposed');
select ok((select qual ~ 'has_active_membership' from pg_policies where tablename='sources'),'AR-073 active Tenant membership predicate');
select ok((select qual ~ 'has_capability' from pg_policies where tablename='source_documents'),'AR-074 Tenant admin governance predicate');
select ok((select qual ~ 'tenant_id' from pg_policies where tablename='source_documents'),'AR-075 scope-bound read predicate');
select ok((select qual ~ 'has_active_membership' from pg_policies where tablename='source_documents'),'AR-076 inactive membership denied by helper');
select ok(not has_table_privilege('authenticated','bios_knowledge.sources','insert'),'AR-077 ordinary direct Source mutation denied');
select ok(not has_table_privilege('authenticated','bios_knowledge.source_documents','update'),'AR-077 ordinary direct Document mutation denied');
select has_function('bios_internal','source_actor',array['uuid','text'],'AR-078/079 internally derived tenant-admin authority');
select has_function('bios_internal','create_source',array['text','text','text','text','text','uuid','text','uuid'],'AR-080 narrow platform Source path');
select results_eq($$select count(*)::bigint from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='bios_internal' and p.proname like '%source%' and p.prosecdef and p.proconfig=array['search_path=""']$$,array[7::bigint],'AR-081 privileged functions fixed empty search_path');
select results_eq($$select count(*)::bigint from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='bios_internal' and p.proname like '%source%' and p.prosecdef and has_function_privilege('public',p.oid,'execute')$$,array[0::bigint],'AR-082 PUBLIC execution denied');
select throws_ok($$delete from bios_knowledge.source_documents where canonical_title='Document Four Corrected'$$,'P0001','Source foundation rows cannot be deleted','AR-083 physical deletion denied');
select results_eq($$select count(*)::bigint from bios_governance.audit_events where resource_type in ('source','source_document') and action in ('reference.created','reference.status_changed','reference.metadata_updated') and outcome='succeeded'$$,array[(select count(*)::bigint from bios_governance.audit_events where resource_type in ('source','source_document'))],'AR-084 deterministic approved audit actions');
select is_empty($$select 1 from bios_governance.audit_events where resource_type='source_document' and outcome='succeeded' and metadata ? 'content'$$,'AR-088 audit contains no document content');
select throws_ok($$insert into bios_governance.audit_events(scope_type,actor_type,actor_identifier,action,resource_type,outcome,metadata) values('platform','service','test','reference.created','unknown_source_object','succeeded','{}')$$,'23514',null,'AR-086 unknown audit resource rejected');
select ok((select count(*)=2 from unnest(array['source','source_document']) r where r=any(array(select distinct resource_type from bios_governance.audit_events where resource_type in ('source','source_document')))),'AR-086 approved audit resources accepted');
select ok((select count(*)=0 from bios_governance.audit_events where resource_type='source_document' and outcome='succeeded' and metadata->>'reason'='bad'),'AR-085 failed operation has no success audit');
select ok((select count(*)=4 from pg_catalog.pg_tables where schemaname='bios_knowledge' and tablename in ('entity_types','entities','entity_aliases','sources')),'AR-089 earlier foundation catalog remains present');
select has_index('bios_knowledge','source_documents','source_documents_candidate_successor_uq','AR-092 concurrency uniqueness index');
select ok((select pg_get_functiondef(p.oid) ~ 'pg_advisory_xact_lock' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='bios_internal' and p.proname='govern_source_document_row'),'AR-092 deterministic advisory lock');

select lives_ok($$select bios_internal.update_source_metadata((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='tenant' and tenant_id='a5000000-0000-0000-0000-000000000002'),'Tenant B Candidate Corrected','candidate','https://b.test','correction','migration-005-test')$$,'AR-097 candidate Source correction');
select lives_ok($$select bios_internal.update_source_metadata((select id from bios_knowledge.sources where code='shared_src' and knowledge_scope='shared'),'Shared Active Corrected','active','https://active.test','correction','migration-005-test')$$,'AR-098 active Source correction');
select lives_ok($$select bios_internal.update_source_metadata((select id from bios_knowledge.sources where code='shared_src2'),'Shared Deprecated Corrected','deprecated','https://deprecated.test','correction','migration-005-test')$$,'AR-099 deprecated Source correction');
select results_eq($$select status from bios_knowledge.sources where code='shared_src2'$$,array['deprecated'],'AR-100 deprecated correction does not reactivate');
select throws_ok($$update bios_knowledge.sources set code='changed' where code='shared_src2'$$,'P0001','Source identity and ownership are immutable','AR-101 Source identity immutable all states');
select ok((select updated_at>created_at from bios_knowledge.sources where code='shared_src2'),'AR-102 Source correction updates updated_at');
select ok((select count(*)>0 from bios_governance.audit_events where resource_type='source' and resource_id=(select id from bios_knowledge.sources where code='shared_src2') and action='reference.metadata_updated'),'AR-102 Source correction audits atomically');

select * from finish();
rollback;
